import{_ as a,o as n,a as p,b as l}from"./app.DKoEZOcr.js";const c="/ascendc.github.io/pr/5487/assets/pipe_task_run_33.uaUmLO_8.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"设计与实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design"},{"text":"核函数（Kernel）侧输出shape依赖计算","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/kernel_output_shape_computation"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/kernel_output_shape_computation.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/kernel_output_shape_computation.md","outlineHeaders":[{"level":2,"title":"在算子原型中标记输出","slug":"在算子原型中标记输出","link":"#在算子原型中标记输出"},{"level":2,"title":"核函数（Kernel）入口增加shape输出参数","slug":"核函数（Kernel）入口增加shape输出参数","link":"#核函数（Kernel）入口增加shape输出参数"},{"level":2,"title":"shape信息排布格式","slug":"shape信息排布格式","link":"#shape信息排布格式"},{"level":2,"title":"写入单个输出shape","slug":"写入单个输出shape","link":"#写入单个输出shape"},{"level":2,"title":"写入多个输出shape","slug":"写入多个输出shape","link":"#写入多个输出shape"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787050286000}'),e={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/kernel_output_shape_computation.md"};function t(o,s,i,h,d,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>输出shape依赖计算</h1><p>本文属于扩展内容，介绍输出shape依赖核函数（Kernel）计算结果时的实现方法。NonZero等算子在核函数（Kernel）计算完成前无法确定实际输出shape。此类输出需要在原型定义中调用<code>OutputShapeDependOnCompute()</code>标记，并由核函数（Kernel）按照固定格式把实际shape写入框架追加的shape输出地址。</p><h2 id="在算子原型中标记输出">在算子原型中标记输出<a class="header-anchor" href="#在算子原型中标记输出">​</a></h2><p><code>OutputShapeDependOnCompute()</code>只能用于输出。以下示例表示输出<code>y</code>的shape需要等待核函数（Kernel）计算结果：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">Output</span><span class="p">(</span><span class="s">&quot;y&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_UINT32</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">OutputShapeDependOnCompute</span><span class="p">();</span>
</code></pre></div><p>算子有多个输出时，只在实际依赖计算的输出上增加该标记。输入输出声明方法见<a href="./operator_prototype_definition.html">算子原型定义</a>。</p><h2 id="核函数（Kernel）入口增加shape输出参数">核函数（Kernel）入口增加shape输出参数<a class="header-anchor" href="#核函数（Kernel）入口增加shape输出参数">​</a></h2><p>框架会在所有普通输出之后、<code>workspace</code>和<code>tiling</code>之前追加一个<code>GM_ADDR</code>参数，用于保存依赖计算的输出shape。核函数（Kernel）入口保持以下顺序：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>输入 -&gt; 普通输出 -&gt; shape输出 -&gt; workspace -&gt; tiling
</code></pre></div><p>示例：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">non_zero_custom</span><span class="p">(</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">shapeOut</span><span class="p">,</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 计算y，并把y的实际shape写入shapeOut。</span>
<span class="p">}</span>
</code></pre></div><p>即使有多个输出依赖计算，也只增加一个shape输出地址。各输出的shape信息在该地址中按原型输出顺序连续排列。</p><h2 id="shape信息排布格式">shape信息排布格式<a class="header-anchor" href="#shape信息排布格式">​</a></h2><p>shape输出按<code>uint64_t</code>数组组织。每个待刷新输出固定占9个<code>uint64_t</code>元素：</p><table><thead><tr><th>偏移</th><th>内容</th></tr></thead><tbody><tr><td><code>0</code></td><td>rank，即实际维度数</td></tr><tr><td><code>1</code>至<code>8</code></td><td>各维度大小，最多8维</td></tr></tbody></table><p>如果有<code>n</code>个输出依赖计算，总空间为<code>n * 9</code>个<code>uint64_t</code>元素。第<code>i</code>个输出从<code>i * 9</code>开始，顺序与算子原型中的输出声明顺序一致。</p><p><img src="`+c+`" alt="shape信息排布示意图"></p><p>对于输出Tensor数据类型为<code>uint64_t</code>的场景，需要把rank值的第31位设置为1，表示后续维度按<code>uint64_t</code>解析：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">UINT64_SHAPE_FLAG</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mh">0x0000000080000000ULL</span><span class="p">;</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">encodedRank</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">UINT64_SHAPE_FLAG</span><span class="w"> </span><span class="o">|</span><span class="w"> </span><span class="n">rank</span><span class="p">;</span>
</code></pre></div><p>输出Tensor为<code>uint32_t</code>时不设置该标记，直接写入rank。</p><h2 id="写入单个输出shape">写入单个输出shape<a class="header-anchor" href="#写入单个输出shape">​</a></h2><p>假设输出<code>y</code>的数据类型为<code>uint32_t</code>，核函数（Kernel）计算后得到实际shape为<code>[32, 64]</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">non_zero_custom</span><span class="p">(</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">shapeOut</span><span class="p">,</span>
<span class="w">    </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 算子计算逻辑，此处省略。</span>

<span class="w">    </span><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">SHAPE_SLOT_SIZE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">9</span><span class="p">;</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">shapeGlobal</span><span class="p">;</span>
<span class="w">    </span><span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span>
<span class="w">        </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint64_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">shapeOut</span><span class="p">),</span><span class="w"> </span><span class="n">SHAPE_SLOT_SIZE</span><span class="p">);</span>

<span class="w">    </span><span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">);</span><span class="w">   </span><span class="c1">// rank</span>
<span class="w">    </span><span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">);</span><span class="w">  </span><span class="c1">// dim[0]</span>
<span class="w">    </span><span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">64</span><span class="p">);</span><span class="w">  </span><span class="c1">// dim[1]</span>
<span class="p">}</span>
</code></pre></div><p>索引3至8是该输出的保留槽位，不会保存其他输出的数据。</p><p>输出Tensor的数据类型为<code>uint64_t</code>，实际shape为<code>[1, 64, 128, 128]</code>时，需要设置类型标记：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">SHAPE_SLOT_SIZE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">9</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">UINT64_SHAPE_FLAG</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mh">0x0000000080000000ULL</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">shapeGlobal</span><span class="p">;</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span>
<span class="w">    </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint64_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">shapeOut</span><span class="p">),</span><span class="w"> </span><span class="n">SHAPE_SLOT_SIZE</span><span class="p">);</span>

<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">UINT64_SHAPE_FLAG</span><span class="w"> </span><span class="o">|</span><span class="w"> </span><span class="mi">4ULL</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">64</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">3</span><span class="p">,</span><span class="w"> </span><span class="mi">128</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">4</span><span class="p">,</span><span class="w"> </span><span class="mi">128</span><span class="p">);</span>
</code></pre></div><h2 id="写入多个输出shape">写入多个输出shape<a class="header-anchor" href="#写入多个输出shape">​</a></h2><p>假设两个输出都依赖计算，数据类型均为<code>uint64_t</code>，实际shape分别为<code>[16, 32]</code>和<code>[1, 16, 16, 32]</code>：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">SHAPE_SLOT_SIZE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">9</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">OUTPUT_COUNT</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">SHAPEOUT_SIZE</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">SHAPE_SLOT_SIZE</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">OUTPUT_COUNT</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">UINT64_SHAPE_FLAG</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mh">0x0000000080000000ULL</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">uint64_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">shapeGlobal</span><span class="p">;</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">(</span>
<span class="w">    </span><span class="k">reinterpret_cast</span><span class="o">&lt;</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint64_t</span><span class="o">*&gt;</span><span class="p">(</span><span class="n">shapeOut</span><span class="p">),</span><span class="w"> </span><span class="n">SHAPEOUT_SIZE</span><span class="p">);</span>

<span class="c1">// 第0个输出：[16, 32]</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span><span class="w"> </span><span class="n">UINT64_SHAPE_FLAG</span><span class="w"> </span><span class="o">|</span><span class="w"> </span><span class="mi">2ULL</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">1</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">2</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">);</span>

<span class="c1">// 第1个输出：[1, 16, 16, 32]，起始偏移为9。</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">9</span><span class="p">,</span><span class="w"> </span><span class="n">UINT64_SHAPE_FLAG</span><span class="w"> </span><span class="o">|</span><span class="w"> </span><span class="mi">4ULL</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">10</span><span class="p">,</span><span class="w"> </span><span class="mi">1</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">11</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">12</span><span class="p">,</span><span class="w"> </span><span class="mi">16</span><span class="p">);</span>
<span class="n">shapeGlobal</span><span class="p">.</span><span class="n">SetValue</span><span class="p">(</span><span class="mi">13</span><span class="p">,</span><span class="w"> </span><span class="mi">32</span><span class="p">);</span>
</code></pre></div><p>当算子还包含不依赖计算的普通输出时，shape输出区域只为调用了<code>OutputShapeDependOnCompute()</code>的输出分配槽位，但槽位顺序仍按这些输出在原型中的先后顺序排列。</p><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>：核函数（Kernel）入口格式和参数顺序。</li><li><a href="./operator_prototype_definition.html">算子原型定义</a>：输入输出声明和shape推导关系。</li><li><a href="../../../../../api/Utils-API/prototype_register_management/OpParamDef/OutputShapeDependOnCompute.html">OutputShapeDependOnCompute</a>：接口定义和工程版本约束。</li></ul></article></div>`,1)])])}const w=a(e,[["render",t]]);export{u as __pageData,w as default};
